INSERT INTO documents (id, owner_id, title, content, version, created_at, updated_at, updated_by) VALUES ('d_welcome', 'u_alice', 'Welcome to Ajaia Docs', '{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Welcome to Ajaia Docs"}]},{"type":"paragraph","content":[{"type":"text","text":"This document belongs to Alice. Bob can "},{"type":"text","text":"edit","marks":[{"type":"bold"}]},{"type":"text","text":" it and Carol can only "},{"type":"text","text":"view","marks":[{"type":"italic"}]},{"type":"text","text":" it. Use Switch user at the top to see it as each of them."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Things to try"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Format some text with the toolbar, then refresh the page. Changes save on their own."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Go back to the document list and import a "},{"type":"text","text":".docx","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":".md","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":".txt","marks":[{"type":"bold"}]},{"type":"text","text":" file."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Press "},{"type":"text","text":"Share","marks":[{"type":"bold"}]},{"type":"text","text":", add a person and pick Can edit or Can view."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Switch to Bob and change something. Switch back to Alice, open "},{"type":"text","text":"History","marks":[{"type":"bold"}]},{"type":"text","text":", and restore the version from before his change."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Download the document as Markdown."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How sharing works"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The owner decides who has access. Editors can change the text. Viewers can only read."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The server checks every request, so a hidden button is never the only protection."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If two people save at the same time, the second is asked whose version to keep. The other version stays in History."}]}]}]}]}', 1, 1794528000000, 1794528000000, 'u_alice');
